import { api, json, readJson } from "@/server/lib/http";
import { int, objectId, oneOf, optStr, str } from "@/server/lib/validate";
import { badRequest } from "@/server/lib/errors";
import { requirePermission } from "@/server/auth/session";
import { parseBillInput } from "@/server/services/bill-input";
import { finalizeBill, TENDER_METHODS, type Tender } from "@/server/services/pos";

/**
 * Finalize a bill with its payments. `idempotencyKey` is generated by the billing screen for each
 * attempt and reused on retry, so a double click or a lost response can never bill twice.
 */
export const POST = api(async (req) => {
  const user = await requirePermission("billing.manage");
  const body = await readJson(req);
  const idempotencyKey = str(body, "idempotencyKey", { min: 8, max: 80, label: "Request key" });
  if (!/^[A-Za-z0-9_-]+$/.test(idempotencyKey)) throw badRequest("Invalid request key.", "idempotencyKey");
  const bill = (body.bill ?? {}) as Record<string, unknown>;
  const input = await parseBillInput(bill);

  const raw = Array.isArray(body.payments) ? body.payments : [];
  if (raw.length > 10) throw badRequest("Too many payments.", "payments");
  const tenders: Tender[] = raw.map((p) => {
    const v = (p ?? {}) as Record<string, unknown>;
    const method = oneOf(v, "method", TENDER_METHODS);
    return {
      method,
      amount: int(v, "amount", { min: 1, max: 100_000_000, label: "Payment amount" }),
      reference: optStr(v, "reference", { max: 120 }),
      giftCardCode: method === "giftcard" ? str(v, "giftCardCode", { max: 40, label: "Gift card code" }) : undefined,
    };
  });

  const result = await finalizeBill(input, tenders, user, {
    idempotencyKey,
    draftId: body.draftId ? objectId(body.draftId, "draftId") : undefined,
  });
  return json({ ...result, invoiceId: String(result.invoiceId) }, result.duplicate ? 200 : 201);
});
